def generate_summary(movements):
    summary = {
        'totalMovements': len(movements),
        'totalCredits': 0.0,
        'totalDebits': 0.0,
        'conciliatedCount': 0,
        'pendingCount': 0,
        'unidentifiedCount': 0,
        'errorCount': 0,
        'duplicateCount': 0,
        'advanceCount': 0,
        'balanceForwardCount': 0,
    }

    for mov in movements:
        status = mov['status']

        if status == 'conciliated':
            summary['conciliatedCount'] += 1
        elif status == 'pending':
            summary['pendingCount'] += 1
        elif status == 'unidentified':
            summary['unidentifiedCount'] += 1
        elif status == 'error':
            summary['errorCount'] += 1
        elif status == 'duplicate':
            summary['duplicateCount'] += 1
        elif status == 'advance':
            summary['advanceCount'] += 1
        elif status == 'balanceForward':
            summary['balanceForwardCount'] += 1

        if mov['creditAmount'] is not None:
            summary['totalCredits'] += mov['creditAmount']
        if mov['debitAmount'] is not None:
            summary['totalDebits'] += mov['debitAmount']

    return summary
