def application_decision(amount, open_invoices, balance):
    """
    Decide la aplicación de un pago basado en facturas abiertas y saldo a favor.

    :param amount: Monto del pago a aplicar.
    :param open_invoices: Lista de dicts con keys {id, balance, dueDate}.
    :param balance: Dict con key 'amount' o 0/None si no hay saldo.
    :return: Dict con 'type', 'invoiceId', 'details'.
    """
    # Asegurar que balance tiene la key amount
    balance_amount = balance.get('amount', 0) if isinstance(balance, dict) else 0

    # Si no hay facturas abiertas
    if not open_invoices:
        if balance_amount > 0:
            return {
                'type': 'balance_forward',
                'details': f'Saldo a favor actualizado: ${balance_amount + amount}'
            }
        else:
            return {
                'type': 'advance',
                'details': 'No hay facturas abiertas. Registrado como anticipo.'
            }

    # Si hay facturas abiertas -> Sortear por FIFO (dueDate ASC)
    # Asumimos que open_invoices viene con dueDate, ordenar para FIFO
    sorted_invoices = sorted(open_invoices, key=lambda x: x.get('dueDate', ''))
    oldest_invoice = sorted_invoices[0]

    # Prioridad a combinación exacta
    for inv in sorted_invoices:
        if inv['balance'] == amount:
            return {
                'type': 'full',
                'invoiceId': inv['id'],
                'details': f'Pago completo de factura {inv["id"]}. Monto: ${amount}'
            }

    # Si no hay exacta, aplicar a la más antigua (FIFO)
    # Si el monto alcanza a pagar la factura antigua (>= balance)
    oldest_balance = oldest_invoice['balance']
    if amount >= oldest_balance:
        return {
            'type': 'full',
            'invoiceId': oldest_invoice['id'],
            'details': f'Factura {oldest_invoice["id"]} totalmente abonada. Pago: ${amount}'
        }
    else:
        # Pago parcial
        remaining = oldest_balance - amount
        return {
            'type': 'partial',
            'invoiceId': oldest_invoice['id'],
            'details': f'Pago parcial de factura {oldest_invoice["id"]}. Pendiente: ${remaining}'
        }
